Vector2 :: struct {
    x: i64
    y: i64
}

SomeStruct :: struct {
    vector1: Vector2*
}

some_value: SomeStruct
some_value.vector1 = ^vector

vector: Vector2
vector.y = 1034

puti(some_value.vector1.y, 4)

Vector :: struct {
    x: i64
    y: i64
}

make_vector :: (x: i64, y: i64) -> Vector {
    return_value: Vector
    return_value.x = x
    return_value.y = y
    ret return_value
}

global_vector: Vector = make_vector(5, 6)
puti(global_vector.x, 1)
puti(global_vector.y, 1)

make_string :: () -> string {
