// Tests a chain of global variable declarations where each depends on
// previously declared globals. Stresses forward declaration resolution
// across multiple levels of dependency.
//
// Expected stdout:
//   puti(A, 2) -> prints 10
//   puti(B, 2) -> prints 20
//   puti(C, 2) -> prints 30
// good

A: int = 10
B: int = A * 2
C: int = A + B

puti(A, 2)
puti(B, 2)
puti(C, 2)

// Tests a large number of global variables all initialized to literal values,
// then summed. Stresses the symbol table and code-generation paths for
// many top-level declarations.
//
// Expected stdout:
//   puti(total, 2) -> prints 45   (1+2+3+4+5+6+7+8+9)
// good

a: int = 1
b: int = 2
c: int = 3
d: int = 4
e: int = 5
f: int = 6
g: int = 7
h: int = 8
i: int = 9

total: int = a + b + c + d + e + f + g + h + i
puti(total, 2)

// Tests a global variable initialized to the result of a complex expression
// involving multiple other globals. Exercises the global initializer path.
//
// Expected stdout:
//   puti(final, 4) -> prints 1250   (50 * 25 = 1250)
// good

width: int = 50
height: int = width / 2
area: int = width * height

puti(area, 4)

// Tests that all integer primitive types (i8, i32, i64) can be declared
// alongside each other and used in arithmetic without confusion.
//
// Expected stdout:
//   puti(sum, 4) -> prints 23016  (7 + 9 + 23000)
// good

byte_val: i8 = 7
int32_val: i32 = 9
int64_val: i64 = 23000

sum: i64 = byte_val + int32_val + int64_val
puti(sum, 5)

// Tests register allocator under pressure: many independent local variables
// live simultaneously in one function scope. If the allocator spills or
// incorrectly reuses registers the sum will be wrong.
//
// Expected stdout:
//   puti(sum, 2) -> prints 36
// good

main :: () {
    a: int = 1
    b: int = 2
    c: int = 3
    d: int = 4
    e: int = 5
    f: int = 6
    g: int = 7
    h: int = 8

    sum: int = a + b + c + d + e + f + g + h
    puti(sum, 2)
}

// Register pressure: deeply chained arithmetic where every intermediate value
// must stay live until used. Forces the allocator to keep many values
// in registers simultaneously.
//
// Expected stdout:
//   result = (1+2)*(3+4) - (5+6)*(7-4) = 3*7 - 11*3 = 21 - 33 = -12
//   puti(result, 2) -> prints -12
// good

a: int = 1 + 2
b: int = 3 + 4
c: int = 5 + 6
d: int = 7 - 4

result: int = a * b - c * d
puti(result, 3)

// Integration: array element accessed inside a function body (local array),
// combined with a global constant. Mixes local array, global constant, and
// function return in one computation.
//
// Expected stdout:
//   puti(result, 2) -> prints 106  (100 + arr[1])  arr[1]=6
// good

OFFSET: i64 = 100

get_second :: () -> int {
    arr: int[3] = [4, 6, 8]
    ret arr[1]
}

result: int = OFFSET + get_second()
puti(result, 3)

// Integration: a function returns a struct and the caller immediately reads
// fields from it — no explicit temporary struct variable needed on the call site.
//
// Expected stdout:
//   puti(pair.a, 2) -> prints 7
//   puti(pair.b, 2) -> prints 13
// good

Pair :: struct {
    a: i64
    b: i64
}

make_pair :: (x: i64, y: i64) -> Pair {
    p: Pair
    p.a = x
    p.b = y
    ret p
}

pair: Pair = make_pair(7, 13)
puti(pair.a, 2)
puti(pair.b, 2)

// Integration: pointer to a struct, function that takes an int and returns
// a modified copy, combined with pointer dereference to supply the argument.
//
// Expected stdout:
//   puti(result, 2) -> prints 20   (val.x=10, doubled=20)
// good

double :: (x: int) -> int {
    ret x * 2
}

Box :: struct {
    x: int
}

val: Box
val.x = 10

ptr: Box* = ^val
result: int = double(ptr.x)
puti(result, 2)

// Tests global constants (declared with ::) referenced inside a function body
// as part of an arithmetic expression. Verifies constant propagation into
// function scope.
//
// Expected stdout:
//   puti(result, 3) -> prints 115
// good

BASE: int = 100
MULTIPLIER: int = 3

compute :: (x: int) -> int {
    ret BASE + x * MULTIPLIER
}

result: int = compute(5)
puti(result, 3)

// Tests a deeply nested arithmetic expression to stress operator precedence
// and the expression tree code generation path.
//
// Expected stdout:
//   result = ((2 + 3) * (4 - 1)) / (5 - 2) = (5 * 3) / 3 = 5
//   puti(result, 1) -> prints 5
// good

result: int = ((2 + 3) * (4 - 1)) / (5 - 2)
puti(result, 1)

// Tests an expression that mixes a struct field, a global constant, and a local
// variable in a single arithmetic expression.
//
// Expected stdout:
//   result = v.x + OFFSET - local_adj = 10 + 100 - 5 = 105
//   puti(result, 3) -> prints 105
// good

OFFSET: int = 100

Vec :: struct {
    x: int
}

v: Vec
v.x = 10

local_adj: int = 5
result: int = v.x + OFFSET - local_adj
puti(result, 3)

// Tests integer division truncation and subtraction ordering.
// Verifies that division truncates toward zero and subtraction is left-associative.
//
// Expected stdout:
//   puti(a, 1) -> prints 3   (7 / 2 = 3, truncated)
//   puti(b, 1) -> prints 4   (10 - 3 - 3 = 4)
// good

a: int = 7 / 2
b: int = 10 - 3 - 3

puti(a, 1)
puti(b, 1)

// Tests reassigning a string variable and verifying .length reflects the new value.
//
// Expected stdout:
//   puti(s.length, 1)  -> prints 2  ("hi")
//   puti(s.length, 1)  -> prints 5  ("world")
// good

s: string = "hi"
puti(s.length, 1)

s = "world"
puti(s.length, 1)

// Tests using string.bytes directly as the first argument to puts,
// mirroring how structs_four accesses .bytes on a struct's string field.
// Verifies .bytes is a valid address-like value usable at a call site.
//
// Expected stdout:
//   puts(s.bytes, s.length) -> prints "compiler"
// good

s: string = "compiler"
puts(s.bytes, s.length)

// Tests a string array where every element is overwritten and then read back
// via puts. Extends arrays_six/seven by covering all three positions.
//
// Expected stdout:
//   puts(arr[0]) -> prints "alpha"
//   puts(arr[1]) -> prints "beta"
//   puts(arr[2]) -> prints "gamma"
// good

arr: string[3] = ["one", "two", "three"]

arr[0] = "alpha"
arr[1] = "beta"
arr[2] = "gamma"

puts(arr[0], arr[0].length)
puts(arr[1], arr[1].length)
puts(arr[2], arr[2].length)

// Tests that global :: constants and global : variables can be freely mixed
// in the same expression at global scope.
//
// Expected stdout:
//   puti(total, 4) -> prints 1056  (1000 + 56)
// good

LARGE: int = 1000
small: int = 56
total: int = LARGE + small
puti(total, 4)

// Tests forward-declared globals used in a function body — the function is
// defined before the globals it references are declared.
//
// Expected stdout:
//   puti(get_total(), 2) -> prints 30
// good

get_total :: () -> int {
    ret X + Y
}

X: int = 10
Y: int = 20

puti(get_total(), 2)

// Tests a global struct that is populated at global scope (not inside main),
// mirroring the pattern used throughout the struct tests.
// Verifies struct fields survive the global initializer phase.
//
// Expected stdout:
//   puti(origin.x, 2) -> prints 0
//   puti(origin.y, 2) -> prints 0
//   puti(offset.x, 2) -> prints 5
//   puti(offset.y, 2) -> prints 10
// good

Vec :: struct {
    x: int
    y: int
}

origin: Vec
origin.x = 0
origin.y = 0

offset: Vec
offset.x = 5
offset.y = 10

puti(origin.x, 1)
puti(origin.y, 1)
puti(offset.x, 1)
puti(offset.y, 2)

// Tests taking the address of a struct field directly (^struct.field),
// then reading back the value through the pointer.
// Verifies that address-of on a field offset is computed correctly.
//
// Expected stdout:
//   puti(w.value, 2)  -> prints 42
//   puti(@ptr, 2)     -> prints 42
// good

Wrapper :: struct {
    value: int
}

w: Wrapper
w.value = 42

ptr: int* = ^w.value

puti(w.value, 2)
puti(@ptr, 2)

// Tests two pointers pointing to two different variables simultaneously.
// Verifies that dereferencing each pointer yields its own variable's value
// and that the pointers don't alias each other.
//
// Expected stdout:
//   puti(@pa, 1) -> prints 10
//   puti(@pb, 1) -> prints 20
// good

a: int = 10
b: int = 20

pa: int* = ^a
pb: int* = ^b

puti(@pa, 2)
puti(@pb, 2)

// Tests reassigning a pointer to point to a different variable.
// Verifies that after reassignment the pointer tracks the new target.
//
// Expected stdout:
//   puti(@ptr, 1) -> prints 10   (pointing at a)
//   puti(@ptr, 1) -> prints 20   (now pointing at b)
// good

a: int = 10
b: int = 20

ptr: int* = ^a
puti(@ptr, 2)

ptr = ^b
puti(@ptr, 2)

// Tests a struct whose fields are used inside an arithmetic expression,
// including overwriting a field with a computed value.
//
// Expected stdout:
//   puti(v.x, 2) -> prints 40
//   puti(v.y, 2) -> prints 100
// good

Vector2 :: struct {
    x: int
    y: int
}

v: Vector2
v.x = 10
v.y = 5

v.x = v.x * 4
v.y = v.x * v.y / 2

puti(v.x, 2)
puti(v.y, 3)

// Tests a struct with four fields to verify field offset calculations
// remain correct as struct size grows beyond two fields.
//
// Expected stdout:
//   puti(r.x, 2) -> prints 1
//   puti(r.y, 2) -> prints 2
//   puti(r.z, 2) -> prints 3
//   puti(r.w, 2) -> prints 4
// good

Quad :: struct {
    x: int
    y: int
    z: int
    w: int
}

r: Quad
r.x = 1
r.y = 2
r.z = 3
r.w = 4

puti(r.x, 2)
puti(r.y, 2)
puti(r.z, 2)
puti(r.w, 2)

// Tests passing a struct field directly as an argument to a function.
// Verifies that field loads are materialized correctly at call sites.
//
// Expected stdout:
//   puti(add(v.x, v.y), 2) -> prints 30
// good

add :: (a: int, b: int) -> int {
    ret a + b
}

Vec :: struct {
    x: int
    y: int
}

v: Vec
v.x = 10
v.y = 20

result: int = add(v.x, v.y)
puti(result, 2)

// Tests a struct containing a bool field alongside int fields.
// Verifies that mixed-type structs compute field offsets correctly.
//
// Expected stdout:
//   puti(s.count, 2) -> prints 7
// good

State :: struct {
    active: bool
    count: int
}

s: State
s.active = true
s.count = 7

puti(s.count, 1)

// Tests writing to a struct through a pointer and then reading the value
// back directly from the original struct variable.
// Verifies pointer store propagates to the underlying memory.
//
// Expected stdout:
//   puti(node.value, 2) -> prints 99
// good

Node :: struct {
    value: int
}

node: Node
node.value = 0

ptr: Node* = ^node
ptr.value = 99

puti(node.value, 2)

// Tests a struct returned from a constructor function where the caller then
// accesses fields immediately on the returned value (no extra temp needed).
//
// Expected stdout:
//   puti(global_v.x, 1) -> prints 7
//   puti(global_v.y, 1) -> prints 8
// good

Vec2 :: struct {
    x: i64
    y: i64
}

make_vec :: (x: i64, y: i64) -> Vec2 {
    v: Vec2
    v.x = x
    v.y = y
    ret v
}

global_v: Vec2 = make_vec(7, 8)
puti(global_v.x, 1)
puti(global_v.y, 1)

// Tests using an array's .length property inside an arithmetic expression,
// ensuring .length is treated as a proper value, not just a printable literal.
//
// Expected stdout:
//   puti(doubled_length, 2) -> prints 10
//   puti(nums[2], 2)        -> prints 30
// good

nums: i64[5] = [10, 20, 30, 40, 50]
doubled_length: i64 = nums.length * 2
puti(doubled_length, 2)
puti(nums[2], 2)

// Tests an array returned from a function where the caller then accesses
// both indexed elements and the .length property on the returned array.
//
// Expected stdout:
//   puti(result[0], 1) -> prints 4
//   puti(result[1], 1) -> prints 5
//   puti(result[2], 1) -> prints 6
//   puti(result.length, 1) -> prints 3
// good

make_array :: () -> int[3] {
    ret [4, 5, 6]
}

result: int[3] = make_array()
puti(result[0], 1)
puti(result[1], 1)
puti(result[2], 1)
puti(result.length, 1)

// Tests passing an array element directly as an argument to a user-defined function.
// Verifies that indexed loads are correctly materialized at call sites.
//
// Expected stdout:
//   puti(result, 2) -> prints 10
// good

double :: (x: int) -> int {
    ret x * 2
}

vals: int[3] = [3, 5, 7]
result: int = double(vals[1])
puti(result, 2)

// Tests an array of structs where multiple fields on multiple elements
// are all written and then read back. Extends arrays_eight with more
// reads to ensure field indexing stays correct across elements.
//
// Expected stdout:
//   puti(pts[0].x, 2) -> prints 1
//   puti(pts[0].y, 2) -> prints 2
//   puti(pts[1].x, 2) -> prints 3
//   puti(pts[1].y, 2) -> prints 4
//   puti(pts[2].x, 2) -> prints 5
//   puti(pts[2].y, 2) -> prints 6
// good

Point :: struct {
    x: i64
    y: i64
}

pts: Point[3]

pts[0].x = 1
pts[0].y = 2
pts[1].x = 3
pts[1].y = 4
pts[2].x = 5
pts[2].y = 6

puti(pts[0].x, 1)
puti(pts[0].y, 1)
puti(pts[1].x, 1)
puti(pts[1].y, 1)
puti(pts[2].x, 1)
puti(pts[2].y, 1)

// Tests overwriting every element of an array and then reading them all back.
// Stresses that element writes are independent and don't alias each other.
//
// Expected stdout:
//   puti(arr[0], 1) -> prints 10
//   puti(arr[1], 1) -> prints 20
//   puti(arr[2], 1) -> prints 30
// good

arr: i64[3] = [1, 2, 3]

arr[0] = 10
arr[1] = 20
arr[2] = 30

puti(arr[0], 2)
puti(arr[1], 2)
puti(arr[2], 2)

// Tests a function with 4 parameters to stress the calling convention
// and register allocation for argument passing.
//
// Expected stdout:
//   puti(result, 2) -> prints 10
// good

add_four :: (a: int, b: int, c: int, d: int) -> int {
    ret a + b + c + d
}

result: int = add_four(1, 2, 3, 4)
puti(result, 2)

// Tests passing a function call as an argument to another function call.
// Verifies that the return value of add_one(5) is correctly passed into double().
//
// Expected stdout:
//   puti(result, 2) -> prints 12
// good

double :: (x: int) -> int {
    ret x * 2
}

add_one :: (x: int) -> int {
    ret x + 1
}

result: int = double(add_one(5))
puti(result, 2)

// Tests a function calling another function internally.
// cube() depends on square(), verifying inter-function call correctness.
//
// Expected stdout:
//   puti(result, 2) -> prints 27
// good

square :: (x: int) -> int {
    ret x * x
}

cube :: (x: int) -> int {
    ret x * square(x)
}

result: int = cube(3)
puti(result, 2)

// Tests calling the same function multiple times with different arguments.
// Verifies that the call frame is correctly reset between invocations.
//
// Expected stdout:
//   puti(r1, 2) -> prints 3
//   puti(r2, 2) -> prints 10
//   puti(r3, 2) -> prints 21
// good

add :: (x: int, y: int) -> int {
    ret x + y
}

r1: int = add(1, 2)
r2: int = add(3, 7)
r3: int = add(10, 11)

puti(r1, 1)
puti(r2, 2)
puti(r3, 2)

// Tests a void function (no return type) that uses several local variables
// and calls puti internally. Verifies void functions clean up the stack correctly.
//
// Expected stdout:
//   puti(product, 2) -> prints 200
// good

print_product :: (a: int, b: int) {
    product: int = a * b
    puti(product, 3)
}

print_product(10, 20)

// Tests a nested function that closes over its outer function's parameter.
// Verifies that closure capture of parameters (not just locals) works correctly.
//
// Expected stdout:
//   puti(inner result, 2) -> prints 15
// good but maybe disabled for now

main :: () {
    scale: int = 5

    multiply :: (x: int) -> int {
        ret x * scale
    }

    result: int = multiply(3)
    puti(result, 2)
}

// Tests a function with f64 parameters and return type.
// Verifies floating-point values survive the call frame round-trip.
//
// Expected stdout:
//   puti(result, 4) -> prints 3 (truncated integer view, runtime-dependent)
//   (the key check is that the bytecode compiles without error)
// maybe?

fsub :: (x: f64, y: f64) -> f64 {
    ret x - y
}

fadd :: (x: f64, y: f64) -> f64 {
    ret x + y
}

a: f64 = fadd(1.5, 2.5)
b: f64 = fsub(10.0, 7.0)

// Tests two top-level functions that call each other in sequence (not mutually
// recursive, just sequentially). Verifies independent call frames don't bleed.
//
// Expected stdout:
//   puti(sum, 2)  -> prints 15
//   puti(diff, 2) -> prints 5
// good

add :: (x: int, y: int) -> int {
    ret x + y
}

sub :: (x: int, y: int) -> int {
    ret x - y
}

sum: int = add(10, 5)
diff: int = sub(10, 5)

puti(sum, 2)
puti(diff, 1)

// Tests a function with three parameters (between the 2-param and 4-param cases).
// Verifies that argument ordering is preserved for odd-numbered parameter counts.
//
// Expected stdout:
//   puti(result, 2) -> prints 6  (1 * 2 * 3)
// good

multiply_three :: (a: int, b: int, c: int) -> int {
    ret a * b * c
}

result: int = multiply_three(1, 2, 3)
puti(result, 1)

// Tests a three-level nested function call chain: outer defines middle,
// middle defines inner, inner reads a variable from outer's scope.
// Stresses closure variable capture across multiple nesting levels.
//
// Expected stdout:
//   puti(bar_value, 3) -> prints 103  (base=100, increment=3, total=103)
// good, but maybe need to disable

main :: () {
    base: int = 100

    outer :: () {
        increment: int = 3

        inner :: () {
            bar_value: int = base + increment
            puti(bar_value, 3)
        }

        inner()
    }

    outer()
}

// Tests that a nested function can be called multiple times and that
// the closure variables it reads remain correct across calls.
//
// Expected stdout (called twice):
//   puti(val, 2) -> prints 50
//   puti(val, 2) -> prints 50
// good

main :: () {
    multiplier: int = 10

    scale :: (x: int) -> int {
        ret x * multiplier
    }

    puti(scale(5), 2)
    puti(scale(5), 2)
}

// Tests two sibling nested functions in the same outer scope, each using
// a different outer variable. Verifies that sibling closures don't share state.
//
// Expected stdout:
//   puti(get_a(), 1) -> prints 10
//   puti(get_b(), 1) -> prints 20
// good

main :: () {
    a: int = 10
    b: int = 20

    get_a :: () -> int {
        ret a
    }

    get_b :: () -> int {
        ret b
    }

    puti(get_a(), 2)
    puti(get_b(), 2)
}

// Tests that global-scope code runs before main is called, and that main
// can read values set up at global scope.
//
// Expected stdout:
//   puts(msg, msg.length) -> prints "setup"
//   puts(msg2, msg2.length) -> prints "main"
// when a main function is defined the global scope is supposed to run and then continue running the main function
// if main function is called inside of global then global is the full program entry point and main just becomes another function

msg: string = "setup"
puts(msg, msg.length)

main :: () {
    msg2: string = "main"
