// Combines struct constructor functions with struct array element assignment.
//
// Expected stdout:
//   puti(items[0].id, 1) -> prints 10
//   puti(items[1].id, 1) -> prints 20
// good

Item :: struct {
    id: i64
}

make_item :: (id: i64) -> Item {
    it: Item
    it.id = id
    ret it
}

items: Item[2]
